export const direitoAdministrativoQuestions: Question[] = [
  {"id": "direito-administrativo-conc-v1-mc-i-01", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Organização administrativa", "subtopic": "Administração indireta", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Integram a Administração Pública indireta", "alternatives": [{"id": "A", "text": "as autarquias, as fundações públicas, as empresas públicas e as sociedades de economia mista"}, {"id": "B", "text": "os ministérios e as secretarias estaduais"}, {"id": "C", "text": "as organizações sociais e as OSCIPs"}, {"id": "D", "text": "as concessionárias e permissionárias de serviço público"}, {"id": "E", "text": "os Poderes Legislativo e Judiciário"}], "correctAnswer": "A", "explanation": "A Administração indireta é formada por pessoas jurídicas criadas ou autorizadas por lei: autarquias, fundações públicas, empresas públicas e sociedades de economia mista. A direta é formada pelos órgãos dos próprios entes federativos.", "alternativeExplanations": {"A": "Correto. Essas são as entidades da Administração indireta.", "B": "Ministérios e secretarias são órgãos da Administração direta.", "C": "Essas entidades são do terceiro setor; colaboram com o Estado, mas não o integram.", "D": "Concessionárias são particulares que prestam serviço por delegação.", "E": "Os Poderes não são entidades da Administração indireta."}, "tags": ["organizacao-administrativa", "administracao-indireta", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-administrativa", "administracao-indireta"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-i-02", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Princípios da Administração", "subtopic": "Princípios expressos", "difficulty": "iniciante", "type": "multiple-choice", "statement": "O art. 37, caput, da Constituição estabelece como princípios da Administração Pública", "alternatives": [{"id": "A", "text": "legalidade, imparcialidade, moralidade, publicidade e economicidade"}, {"id": "B", "text": "legalidade, impessoalidade, moralidade, publicidade e eficiência"}, {"id": "C", "text": "legitimidade, impessoalidade, moralidade, probidade e eficiência"}, {"id": "D", "text": "legalidade, impessoalidade, motivação, publicidade e eficácia"}, {"id": "E", "text": "supremacia, indisponibilidade, moralidade, publicidade e eficiência"}], "correctAnswer": "B", "explanation": "O caput do art. 37 traz cinco princípios expressos: legalidade, impessoalidade, moralidade, publicidade e eficiência. A eficiência foi incluída pela Emenda Constitucional 19/1998.", "alternativeExplanations": {"A": "Imparcialidade e economicidade não estão no caput do art. 37.", "B": "Correto. É o conhecido LIMPE.", "C": "Legitimidade e probidade não estão no caput do art. 37.", "D": "Motivação e eficácia não estão no caput do art. 37.", "E": "Supremacia e indisponibilidade do interesse público são princípios implícitos."}, "tags": ["principios", "limpe", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["principios", "limpe"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-i-03", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Poderes administrativos", "subtopic": "Poder de polícia", "difficulty": "iniciante", "type": "multiple-choice", "statement": "A vigilância sanitária interdita um restaurante que descumpria normas de higiene. Essa atuação é manifestação do poder", "alternatives": [{"id": "A", "text": "hierárquico"}, {"id": "B", "text": "disciplinar"}, {"id": "C", "text": "de polícia"}, {"id": "D", "text": "regulamentar"}, {"id": "E", "text": "vinculado"}], "correctAnswer": "C", "explanation": "O poder de polícia é a atividade do Estado que limita ou condiciona o exercício de direitos individuais, como liberdade e propriedade, em favor do interesse público. Fiscalização sanitária, de trânsito e de obras são exemplos.", "alternativeExplanations": {"A": "O poder hierárquico organiza a relação entre órgãos e agentes da própria Administração.", "B": "O poder disciplinar pune servidores e quem tem vínculo especial com a Administração.", "C": "Correto. O poder de polícia limita atividades particulares em benefício do interesse coletivo.", "D": "O poder regulamentar serve para editar regulamentos que detalham as leis.", "E": "Vinculado descreve o grau de liberdade do ato, não o poder de limitar atividades privadas."}, "tags": ["poderes-administrativos", "poder-de-policia", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["poderes-administrativos", "poder-de-policia"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-i-04", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Princípios da Administração", "subtopic": "Legalidade", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Pelo princípio da legalidade aplicado à Administração Pública, o administrador", "alternatives": [{"id": "A", "text": "pode fazer tudo o que a lei não proíbe"}, {"id": "B", "text": "pode agir conforme sua vontade, desde que de boa-fé"}, {"id": "C", "text": "está dispensado de seguir a lei em casos urgentes"}, {"id": "D", "text": "só pode fazer o que a lei permite ou autoriza"}, {"id": "E", "text": "segue a lei apenas nos atos vinculados"}], "correctAnswer": "D", "explanation": "Para o particular, vale a autonomia da vontade: pode fazer tudo o que a lei não proíbe. Para a Administração, a legalidade é estrita: o agente só pode fazer o que a lei permite ou autoriza.", "alternativeExplanations": {"A": "Essa é a legalidade aplicada aos particulares.", "B": "A boa-fé não substitui a autorização legal.", "C": "Mesmo nas urgências a Administração age dentro da lei.", "D": "Correto. Para a Administração, a legalidade é estrita.", "E": "Os atos discricionários também estão sujeitos à lei."}, "tags": ["principios", "legalidade", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["principios", "legalidade"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-i-05", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Licitações e contratos", "subtopic": "Modalidades", "difficulty": "iniciante", "type": "multiple-choice", "statement": "NÃO é modalidade de licitação prevista na Lei 14.133/2021", "alternatives": [{"id": "A", "text": "o pregão"}, {"id": "B", "text": "a concorrência"}, {"id": "C", "text": "o leilão"}, {"id": "D", "text": "o diálogo competitivo"}, {"id": "E", "text": "a tomada de preços"}], "correctAnswer": "E", "explanation": "A Lei 14.133/2021 prevê cinco modalidades: pregão, concorrência, concurso, leilão e diálogo competitivo. A tomada de preços e o convite, da antiga Lei 8.666/1993, deixaram de existir.", "alternativeExplanations": {"A": "O pregão é modalidade da Lei 14.133.", "B": "A concorrência é modalidade da Lei 14.133.", "C": "O leilão é modalidade da Lei 14.133.", "D": "O diálogo competitivo é modalidade criada pela Lei 14.133.", "E": "Correto. Tomada de preços e convite existiam na Lei 8.666/1993 e não foram mantidos na lei nova."}, "tags": ["licitacoes", "modalidades", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["licitacoes", "modalidades"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-i-06", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Poderes administrativos", "subtopic": "Poder disciplinar", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Após processo regular, a chefia aplica advertência a um servidor que descumpriu um dever funcional. A Administração exerceu o poder", "alternatives": [{"id": "A", "text": "disciplinar"}, {"id": "B", "text": "de polícia"}, {"id": "C", "text": "regulamentar"}, {"id": "D", "text": "normativo das agências"}, {"id": "E", "text": "de império sobre particulares"}], "correctAnswer": "A", "explanation": "O poder disciplinar permite à Administração apurar infrações e aplicar penalidades a servidores e a outras pessoas sujeitas à disciplina administrativa, como contratados. A aplicação depende de processo com contraditório e ampla defesa.", "alternativeExplanations": {"A": "Correto. O poder disciplinar permite apurar infrações e punir servidores.", "B": "O poder de polícia atinge os particulares em geral, não os servidores por infrações funcionais.", "C": "O poder regulamentar serve para editar normas complementares às leis.", "D": "Não se trata de editar normas, mas de punir uma infração.", "E": "A punição decorre do vínculo funcional, não de supremacia geral sobre particulares."}, "tags": ["poderes-administrativos", "poder-disciplinar", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["poderes-administrativos", "poder-disciplinar"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-i-07", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Servidores públicos", "subtopic": "Penalidades", "difficulty": "iniciante", "type": "multiple-choice", "statement": "NÃO é penalidade disciplinar prevista no art. 127 da Lei 8.112/1990", "alternatives": [{"id": "A", "text": "a advertência"}, {"id": "B", "text": "a prisão administrativa"}, {"id": "C", "text": "a suspensão"}, {"id": "D", "text": "a demissão"}, {"id": "E", "text": "a cassação de aposentadoria"}], "correctAnswer": "B", "explanation": "O art. 127 da Lei 8.112/1990 prevê: advertência, suspensão, demissão, cassação de aposentadoria ou disponibilidade, destituição de cargo em comissão e destituição de função comissionada.", "alternativeExplanations": {"A": "A advertência é penalidade prevista no art. 127.", "B": "Correto. A Lei 8.112 não prevê prisão como penalidade disciplinar.", "C": "A suspensão é penalidade prevista no art. 127.", "D": "A demissão é penalidade prevista no art. 127.", "E": "A cassação de aposentadoria ou disponibilidade é penalidade prevista no art. 127."}, "tags": ["servidores-publicos", "lei-8112", "penalidades", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["servidores-publicos", "lei-8112", "penalidades"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-m-01", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Anulação e revogação", "difficulty": "medio", "type": "multiple-choice", "statement": "Segundo a Súmula 473 do STF, a Administração pode", "alternatives": [{"id": "A", "text": "revogar atos ilegais e anular atos inconvenientes"}, {"id": "B", "text": "anular seus atos somente com autorização judicial"}, {"id": "C", "text": "anular seus próprios atos ilegais e revogar os inconvenientes ou inoportunos, respeitados os direitos adquiridos"}, {"id": "D", "text": "revogar atos vinculados a qualquer tempo"}, {"id": "E", "text": "nunca rever seus próprios atos depois de publicados"}], "correctAnswer": "C", "explanation": "A Súmula 473 do STF diz que a Administração pode anular seus atos ilegais, porque deles não se originam direitos, ou revogá-los por conveniência ou oportunidade, respeitados os direitos adquiridos e ressalvada a apreciação judicial.", "alternativeExplanations": {"A": "É o contrário: ato ilegal se anula; ato inconveniente se revoga.", "B": "A autotutela permite anular sem precisar do Judiciário.", "C": "Correto. É o conteúdo da Súmula 473, que expressa a autotutela.", "D": "Atos vinculados não podem ser revogados, pois não há juízo de conveniência.", "E": "A autotutela permite rever os próprios atos."}, "tags": ["atos-administrativos", "autotutela", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos", "autotutela"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-m-02", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Elementos", "difficulty": "medio", "type": "multiple-choice", "statement": "São elementos (ou requisitos) do ato administrativo", "alternatives": [{"id": "A", "text": "presunção de legitimidade, imperatividade, autoexecutoriedade e tipicidade"}, {"id": "B", "text": "legalidade, impessoalidade, moralidade, publicidade e eficiência"}, {"id": "C", "text": "vontade, capacidade, publicidade e prazo"}, {"id": "D", "text": "competência, finalidade, forma, motivo e objeto"}, {"id": "E", "text": "ofício, despacho, parecer e portaria"}], "correctAnswer": "D", "explanation": "Os elementos do ato administrativo são competência (quem pode praticar), finalidade (interesse público), forma (como se exterioriza), motivo (fato e fundamento) e objeto (o efeito produzido). Os atributos são presunção de legitimidade, imperatividade, autoexecutoriedade e tipicidade.", "alternativeExplanations": {"A": "Esses são atributos, não elementos.", "B": "Esses são princípios da Administração.", "C": "Essa não é a classificação adotada para os atos administrativos.", "D": "Correto. São os cinco elementos clássicos do ato administrativo.", "E": "Esses são tipos de documentos ou espécies de atos, não elementos."}, "tags": ["atos-administrativos", "elementos", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos", "elementos"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-m-03", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Responsabilidade civil do Estado", "subtopic": "Responsabilidade objetiva", "difficulty": "medio", "type": "multiple-choice", "statement": "Um veículo da prefeitura, dirigido por um servidor em serviço, atinge o carro de um cidadão. De acordo com o art. 37, § 6º, da Constituição,", "alternatives": [{"id": "A", "text": "o cidadão precisa provar a culpa do motorista para ser indenizado"}, {"id": "B", "text": "apenas o servidor responde, com seu próprio patrimônio"}, {"id": "C", "text": "o Município só responde se o servidor tiver agido com dolo"}, {"id": "D", "text": "não há responsabilidade, porque o servidor estava em serviço"}, {"id": "E", "text": "o Município responde objetivamente pelo dano e pode cobrar do servidor, em regresso, se ele agiu com dolo ou culpa"}], "correctAnswer": "E", "explanation": "Pelo art. 37, § 6º, as pessoas jurídicas de direito público e as de direito privado prestadoras de serviço público respondem pelos danos que seus agentes, nessa qualidade, causarem a terceiros. A responsabilidade é objetiva, e o Estado pode cobrar do agente se ele agiu com dolo ou culpa.", "alternativeExplanations": {"A": "A responsabilidade do Estado é objetiva: não depende de culpa.", "B": "Quem responde perante a vítima é o Estado.", "C": "Dolo ou culpa só importam para o regresso contra o servidor.", "D": "Justamente por estar em serviço, o Estado responde.", "E": "Correto. É a responsabilidade objetiva com direito de regresso."}, "tags": ["responsabilidade-civil", "risco-administrativo", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["responsabilidade-civil", "risco-administrativo"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-m-04", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Organização administrativa", "subtopic": "Criação de entidades", "difficulty": "medio", "type": "multiple-choice", "statement": "Pelo art. 37, XIX, da Constituição, somente por lei específica poderá ser criada a seguinte entidade:", "alternatives": [{"id": "A", "text": "autarquia"}, {"id": "B", "text": "empresa pública"}, {"id": "C", "text": "sociedade de economia mista"}, {"id": "D", "text": "subsidiária de empresa estatal"}, {"id": "E", "text": "consórcio entre empresas privadas"}], "correctAnswer": "A", "explanation": "O art. 37, XIX, diz que somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, sociedade de economia mista e fundação. Nessas, a lei autoriza e o registro do ato constitutivo cria a entidade.", "alternativeExplanations": {"A": "Correto. A autarquia é criada diretamente pela lei.", "B": "Para a empresa pública, a lei apenas autoriza a criação.", "C": "Para a sociedade de economia mista, a lei apenas autoriza a criação.", "D": "Subsidiárias dependem de autorização legislativa, não são criadas pela lei.", "E": "Consórcio privado não é entidade da Administração."}, "tags": ["organizacao-administrativa", "autarquia", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-administrativa", "autarquia"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-m-05", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Processo administrativo", "subtopic": "Recursos", "difficulty": "medio", "type": "multiple-choice", "statement": "Pela Lei 9.784/1999, salvo disposição legal específica, o prazo para interpor recurso administrativo é de", "alternatives": [{"id": "A", "text": "5 dias, contado da decisão"}, {"id": "B", "text": "10 dias, contado da ciência ou da divulgação oficial da decisão"}, {"id": "C", "text": "15 dias úteis"}, {"id": "D", "text": "30 dias, contado da ciência"}, {"id": "E", "text": "60 dias"}], "correctAnswer": "B", "explanation": "O art. 59 da Lei 9.784/1999 fixa em 10 dias o prazo para recurso. O recurso é dirigido à autoridade que decidiu, que pode reconsiderar em 5 dias ou encaminhá-lo à autoridade superior, e deve ser decidido em até 30 dias.", "alternativeExplanations": {"A": "5 dias é o prazo para a autoridade reconsiderar antes de encaminhar o recurso.", "B": "Correto. É o prazo do art. 59.", "C": "A Lei 9.784 fixa 10 dias para o recurso.", "D": "30 dias é o prazo para decidir o recurso, não para interpô-lo.", "E": "Não há prazo de 60 dias para recurso na Lei 9.784."}, "tags": ["processo-administrativo", "lei-9784", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["processo-administrativo", "lei-9784"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-m-06", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Improbidade administrativa", "subtopic": "Elemento subjetivo", "difficulty": "medio", "type": "multiple-choice", "statement": "Após as alterações da Lei 14.230/2021, os atos de improbidade administrativa", "alternatives": [{"id": "A", "text": "podem ser culposos quando causam prejuízo ao erário"}, {"id": "B", "text": "são apurados apenas na esfera penal"}, {"id": "C", "text": "exigem conduta dolosa, não existindo mais improbidade culposa"}, {"id": "D", "text": "independem de qualquer vontade do agente"}, {"id": "E", "text": "prescrevem em dois anos contados do fato"}], "correctAnswer": "C", "explanation": "A Lei 14.230/2021 alterou a Lei 8.429/1992 e passou a exigir dolo para todos os atos de improbidade: enriquecimento ilícito, prejuízo ao erário e atentado aos princípios. A mera ilegalidade, sem dolo, não basta.", "alternativeExplanations": {"A": "A modalidade culposa por dano ao erário foi eliminada.", "B": "A improbidade tem natureza civil e é apurada em ação própria.", "C": "Correto. A lei passou a exigir dolo para todos os tipos de improbidade.", "D": "A lei exige dolo, ou seja, vontade livre e consciente.", "E": "O prazo de prescrição é de oito anos."}, "tags": ["improbidade", "lei-14230", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["improbidade", "lei-14230"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-m-07", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Agentes públicos", "subtopic": "Cargo em comissão e função de confiança", "difficulty": "medio", "type": "multiple-choice", "statement": "Sobre cargos em comissão e funções de confiança, é correto afirmar, de acordo com o art. 37, V, da Constituição, que", "alternatives": [{"id": "A", "text": "os cargos em comissão podem ser destinados a qualquer atividade, inclusive técnica permanente"}, {"id": "B", "text": "as funções de confiança podem ser ocupadas por qualquer pessoa, sem vínculo com a Administração"}, {"id": "C", "text": "os cargos em comissão exigem aprovação prévia em concurso público"}, {"id": "D", "text": "as funções de confiança são exercidas exclusivamente por servidores ocupantes de cargo efetivo"}, {"id": "E", "text": "as funções de confiança garantem estabilidade a quem as exerce"}], "correctAnswer": "D", "explanation": "Pelo art. 37, V, as funções de confiança são exercidas exclusivamente por servidores de cargo efetivo, e os cargos em comissão são preenchidos por servidores de carreira nos casos e percentuais mínimos da lei. Ambos destinam-se apenas a direção, chefia e assessoramento.", "alternativeExplanations": {"A": "Os cargos em comissão destinam-se apenas a direção, chefia e assessoramento.", "B": "As funções de confiança são exclusivas de servidores efetivos.", "C": "Cargos em comissão são de livre nomeação e exoneração.", "D": "Correto. É o que diz o art. 37, V.", "E": "Funções de confiança são de livre designação e dispensa."}, "tags": ["agentes-publicos", "cargo-em-comissao", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["agentes-publicos", "cargo-em-comissao"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-a-01", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Atributos", "difficulty": "avancado", "type": "multiple-choice", "statement": "A Administração demole, sem precisar recorrer ao Judiciário, uma construção que ameaça desabar sobre a via pública. O atributo do ato administrativo que permite essa atuação direta é a", "alternatives": [{"id": "A", "text": "presunção de legitimidade"}, {"id": "B", "text": "imperatividade"}, {"id": "C", "text": "tipicidade"}, {"id": "D", "text": "motivação"}, {"id": "E", "text": "autoexecutoriedade"}], "correctAnswer": "E", "explanation": "A autoexecutoriedade permite que a Administração execute suas decisões por meios próprios, sem autorização judicial prévia, quando a lei autoriza ou em situações de urgência, como a demolição de imóvel em risco ou a apreensão de alimentos estragados.", "alternativeExplanations": {"A": "A presunção de legitimidade faz o ato ser tido como válido até prova em contrário.", "B": "A imperatividade impõe obrigações ao particular independentemente de sua concordância, mas não trata da execução direta.", "C": "A tipicidade exige que o ato corresponda a uma figura prevista em lei.", "D": "A motivação é a exposição dos motivos do ato, não um atributo de execução.", "E": "Correto. A autoexecutoriedade permite executar a decisão diretamente, sem ordem judicial prévia."}, "tags": ["atos-administrativos", "atributos", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos", "atributos"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-a-02", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Processo administrativo", "subtopic": "Decadência", "difficulty": "avancado", "type": "multiple-choice", "statement": "Pela Lei 9.784/1999, o direito da Administração de anular atos de que decorram efeitos favoráveis aos destinatários decai, salvo comprovada má-fé, em", "alternatives": [{"id": "A", "text": "5 anos, contados da data em que foram praticados"}, {"id": "B", "text": "2 anos"}, {"id": "C", "text": "10 anos"}, {"id": "D", "text": "20 anos"}, {"id": "E", "text": "não há prazo, pois atos ilegais podem ser anulados a qualquer tempo"}], "correctAnswer": "A", "explanation": "O art. 54 da Lei 9.784/1999 estabelece que o direito de anular atos favoráveis aos destinatários decai em cinco anos, salvo má-fé comprovada. A regra protege a segurança jurídica e a confiança de quem recebeu o benefício.", "alternativeExplanations": {"A": "Correto. É o prazo decadencial do art. 54.", "B": "O prazo do art. 54 é de cinco anos.", "C": "O prazo do art. 54 é de cinco anos.", "D": "O prazo do art. 54 é de cinco anos.", "E": "A Lei 9.784 fixa prazo para proteger a segurança jurídica de quem está de boa-fé."}, "tags": ["processo-administrativo", "decadencia", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["processo-administrativo", "decadencia"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-a-03", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Licitações e contratos", "subtopic": "Critérios de julgamento", "difficulty": "avancado", "type": "multiple-choice", "statement": "Na Lei 14.133/2021, o leilão é usado para alienar imóveis ou bens móveis inservíveis ou legalmente apreendidos. Seu critério de julgamento é o", "alternatives": [{"id": "A", "text": "menor preço"}, {"id": "B", "text": "maior lance"}, {"id": "C", "text": "técnica e preço"}, {"id": "D", "text": "melhor técnica ou conteúdo artístico"}, {"id": "E", "text": "maior desconto"}], "correctAnswer": "B", "explanation": "Pela Lei 14.133/2021, o leilão serve para alienar imóveis ou bens móveis inservíveis ou legalmente apreendidos, a quem oferecer o maior lance. Os demais critérios (menor preço, maior desconto, melhor técnica, técnica e preço, maior retorno econômico) servem a outras modalidades.", "alternativeExplanations": {"A": "Menor preço é critério típico de compras, não de venda de bens.", "B": "Correto. No leilão vence quem oferece o maior lance.", "C": "Técnica e preço serve a serviços em que a técnica pesa na escolha.", "D": "Esse critério é usado, por exemplo, no concurso.", "E": "Maior desconto é usado em contratações com base em tabela de preços."}, "tags": ["licitacoes", "leilao", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["licitacoes", "leilao"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-a-04", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Servidores públicos", "subtopic": "Formas de provimento", "difficulty": "avancado", "type": "multiple-choice", "statement": "Um servidor estável foi demitido, mas uma decisão judicial invalidou a demissão. Seu retorno ao cargo anteriormente ocupado, com ressarcimento das vantagens, chama-se", "alternatives": [{"id": "A", "text": "reversão"}, {"id": "B", "text": "recondução"}, {"id": "C", "text": "reintegração"}, {"id": "D", "text": "aproveitamento"}, {"id": "E", "text": "readaptação"}], "correctAnswer": "C", "explanation": "Pelo art. 28 da Lei 8.112/1990, reintegração é a reinvestidura do servidor estável no cargo anteriormente ocupado quando invalidada sua demissão por decisão administrativa ou judicial, com ressarcimento de todas as vantagens.", "alternativeExplanations": {"A": "Reversão é o retorno do servidor aposentado à atividade.", "B": "Recondução é o retorno ao cargo anterior por inabilitação no estágio probatório ou por reintegração do antigo ocupante.", "C": "Correto. A reintegração ocorre quando a demissão é invalidada por decisão administrativa ou judicial.", "D": "Aproveitamento é o retorno do servidor em disponibilidade.", "E": "Readaptação é a investidura em cargo compatível com limitação física ou mental."}, "tags": ["servidores-publicos", "provimento", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["servidores-publicos", "provimento"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-a-05", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Responsabilidade civil do Estado", "subtopic": "Ação contra o agente", "difficulty": "avancado", "type": "multiple-choice", "statement": "De acordo com a tese fixada pelo STF no Tema 940 de repercussão geral, a ação de indenização por dano causado por agente público no exercício da função deve ser proposta", "alternatives": [{"id": "A", "text": "diretamente contra o servidor, apenas"}, {"id": "B", "text": "contra o Estado e o agente, obrigatoriamente juntos"}, {"id": "C", "text": "contra o chefe do Poder Executivo, pessoalmente"}, {"id": "D", "text": "contra o Estado ou a pessoa jurídica de direito privado prestadora de serviço público, e não diretamente contra o agente"}, {"id": "E", "text": "somente na esfera administrativa, sem ação judicial"}], "correctAnswer": "D", "explanation": "No Tema 940, o STF fixou que a ação por danos causados por agente público deve ser ajuizada contra o Estado ou a pessoa jurídica de direito privado prestadora de serviço público, assegurado o direito de regresso contra o responsável em caso de dolo ou culpa.", "alternativeExplanations": {"A": "O STF entendeu que a vítima não pode acionar diretamente o agente.", "B": "A ação é contra a pessoa jurídica; o agente responde depois, em regresso.", "C": "O chefe do Executivo não responde pessoalmente pelos atos dos agentes.", "D": "Correto. É a tese da dupla garantia.", "E": "A vítima pode buscar a indenização judicialmente."}, "tags": ["responsabilidade-civil", "stf", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["responsabilidade-civil", "stf"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-mc-a-06", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Licitações e contratos", "subtopic": "Diálogo competitivo", "difficulty": "avancado", "type": "multiple-choice", "statement": "A Administração precisa contratar uma solução inovadora e não sabe definir sozinha a melhor alternativa técnica. Pela Lei 14.133/2021, a modalidade em que ela conversa com licitantes previamente selecionados para desenvolver alternativas, antes das propostas finais, é o", "alternatives": [{"id": "A", "text": "pregão"}, {"id": "B", "text": "concurso"}, {"id": "C", "text": "leilão"}, {"id": "D", "text": "credenciamento"}, {"id": "E", "text": "diálogo competitivo"}], "correctAnswer": "E", "explanation": "O diálogo competitivo, criado pela Lei 14.133/2021, é usado em contratações de obras, serviços e compras em que a Administração dialoga com licitantes selecionados para desenvolver alternativas, por exemplo em inovação tecnológica, e depois recebe as propostas finais.", "alternativeExplanations": {"A": "O pregão serve a bens e serviços comuns, já bem definidos.", "B": "O concurso escolhe trabalho técnico, científico ou artístico, com prêmio ou remuneração.", "C": "O leilão serve para alienar bens.", "D": "Credenciamento é procedimento auxiliar, não modalidade de licitação.", "E": "Correto. Essa é a característica do diálogo competitivo."}, "tags": ["licitacoes", "dialogo-competitivo", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["licitacoes", "dialogo-competitivo"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-i-01", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Organização administrativa", "subtopic": "Administração direta", "difficulty": "iniciante", "type": "true-false", "statement": "A Administração direta é formada pelos órgãos integrados na estrutura dos entes federativos, como os ministérios e as secretarias.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A Administração direta é o conjunto de órgãos que integram a própria pessoa política (União, Estados, DF e Municípios), sem personalidade jurídica própria.", "alternativeExplanations": {"V": "Correto. Ministérios e secretarias são órgãos da Administração direta.", "F": "Incorreto. Ministérios e secretarias são órgãos da Administração direta."}, "tags": ["organizacao-administrativa", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-administrativa"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-i-02", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Organização administrativa", "subtopic": "Administração indireta", "difficulty": "iniciante", "type": "true-false", "statement": "As empresas públicas e as sociedades de economia mista integram a Administração direta.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Empresas públicas e sociedades de economia mista são entidades da Administração indireta, com personalidade jurídica própria.", "alternativeExplanations": {"V": "Incorreto. Elas integram a Administração indireta.", "F": "Correto. Elas integram a Administração indireta."}, "tags": ["organizacao-administrativa", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-administrativa"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-i-03", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Princípios da Administração", "subtopic": "Publicidade", "difficulty": "iniciante", "type": "true-false", "statement": "O princípio da publicidade exige, em regra, a divulgação oficial dos atos administrativos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A publicidade garante transparência e controle. As exceções são os casos de sigilo previstos em lei, como os necessários à segurança da sociedade e do Estado.", "alternativeExplanations": {"V": "Correto. A divulgação é a regra; o sigilo, a exceção.", "F": "Incorreto. A divulgação é a regra; o sigilo, a exceção."}, "tags": ["principios", "publicidade", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["principios", "publicidade"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-i-04", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Servidores públicos", "subtopic": "Posse", "difficulty": "iniciante", "type": "true-false", "statement": "Pela Lei 8.112/1990, a posse em cargo público ocorre no prazo de 30 dias contados da publicação do ato de provimento.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É o que prevê o art. 13, § 1º, da Lei 8.112/1990. Depois da posse, o servidor tem 15 dias para entrar em exercício.", "alternativeExplanations": {"V": "Correto. O prazo de posse é de 30 dias.", "F": "Incorreto. O prazo de posse é de 30 dias."}, "tags": ["servidores-publicos", "lei-8112", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["servidores-publicos", "lei-8112"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-i-05", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Princípios da Administração", "subtopic": "Impessoalidade", "difficulty": "iniciante", "type": "true-false", "statement": "Pelo princípio da impessoalidade, a publicidade oficial pode trazer nomes e imagens que promovam pessoalmente o governante.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O art. 37, § 1º, proíbe que a publicidade dos órgãos públicos contenha nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores.", "alternativeExplanations": {"V": "Incorreto. A Constituição proíbe a promoção pessoal na publicidade oficial.", "F": "Correto. A Constituição proíbe a promoção pessoal na publicidade oficial."}, "tags": ["principios", "impessoalidade", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["principios", "impessoalidade"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-i-06", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Licitações e contratos", "subtopic": "Pregão", "difficulty": "iniciante", "type": "true-false", "statement": "O pregão é a modalidade de licitação obrigatória para a aquisição de bens e serviços comuns.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "Pela Lei 14.133/2021, o pregão é obrigatório para bens e serviços comuns, aqueles cujos padrões de desempenho e qualidade podem ser definidos de forma objetiva pelo edital.", "alternativeExplanations": {"V": "Correto. Bens e serviços comuns são licitados por pregão.", "F": "Incorreto. Bens e serviços comuns são licitados por pregão."}, "tags": ["licitacoes", "pregao", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["licitacoes", "pregao"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-i-07", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Revogação", "difficulty": "iniciante", "type": "true-false", "statement": "Na revogação, a Administração retira do mundo jurídico um ato ilegal.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Ato ilegal é anulado. A revogação retira um ato válido que se tornou inconveniente ou inoportuno.", "alternativeExplanations": {"V": "Incorreto. Ato ilegal se anula; a revogação atinge ato válido.", "F": "Correto. Ato ilegal se anula; a revogação atinge ato válido."}, "tags": ["atos-administrativos", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-m-01", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Discricionariedade", "difficulty": "medio", "type": "true-false", "statement": "Os atos discricionários permitem ao administrador avaliar, dentro dos limites da lei, a conveniência e a oportunidade de sua prática.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "No ato discricionário, a lei dá margem de escolha ao administrador (mérito administrativo). No ato vinculado, a lei define todos os elementos e não há escolha.", "alternativeExplanations": {"V": "Correto. Conveniência e oportunidade formam o mérito do ato discricionário.", "F": "Incorreto. Conveniência e oportunidade formam o mérito do ato discricionário."}, "tags": ["atos-administrativos", "discricionariedade", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos", "discricionariedade"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-m-02", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Organização administrativa", "subtopic": "Sociedade de economia mista", "difficulty": "medio", "type": "true-false", "statement": "As sociedades de economia mista podem adotar qualquer forma societária, como a de sociedade limitada.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A sociedade de economia mista deve ser constituída sob a forma de sociedade anônima (Lei 13.303/2016). A empresa pública pode adotar qualquer forma admitida em direito.", "alternativeExplanations": {"V": "Incorreto. A sociedade de economia mista é sempre S.A.", "F": "Correto. A sociedade de economia mista é sempre S.A."}, "tags": ["organizacao-administrativa", "estatais", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-administrativa", "estatais"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-m-03", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Servidores públicos", "subtopic": "Penalidades", "difficulty": "medio", "type": "true-false", "statement": "Pela Lei 8.112/1990, a suspensão aplicada ao servidor não pode exceder 90 dias.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 130 da Lei 8.112/1990 limita a suspensão a 90 dias. Quando houver conveniência para o serviço, ela pode ser convertida em multa de 50% por dia de remuneração.", "alternativeExplanations": {"V": "Correto. O limite da suspensão é de 90 dias.", "F": "Incorreto. O limite da suspensão é de 90 dias."}, "tags": ["servidores-publicos", "penalidades", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["servidores-publicos", "penalidades"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-m-04", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Processo administrativo", "subtopic": "Instâncias", "difficulty": "medio", "type": "true-false", "statement": "No processo administrativo federal, o recurso tramita por no máximo três instâncias administrativas, salvo disposição legal diversa.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É o que prevê o art. 57 da Lei 9.784/1999.", "alternativeExplanations": {"V": "Correto. O art. 57 da Lei 9.784 fixa três instâncias.", "F": "Incorreto. O art. 57 da Lei 9.784 fixa três instâncias."}, "tags": ["processo-administrativo", "lei-9784", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["processo-administrativo", "lei-9784"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-m-05", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Presunção de legitimidade", "difficulty": "medio", "type": "true-false", "statement": "A presunção de legitimidade dos atos administrativos é absoluta e não admite prova em contrário.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A presunção de legitimidade é relativa: o ato é tido como válido até que se prove o contrário, e o ônus da prova cabe a quem alega a ilegalidade.", "alternativeExplanations": {"V": "Incorreto. A presunção é relativa e admite prova em contrário.", "F": "Correto. A presunção é relativa e admite prova em contrário."}, "tags": ["atos-administrativos", "atributos", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos", "atributos"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-m-06", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Responsabilidade civil do Estado", "subtopic": "Responsabilidade objetiva", "difficulty": "medio", "type": "true-false", "statement": "Para obter indenização do Estado por dano causado por agente público em serviço, a vítima sempre precisa provar a culpa do serviço.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Pelo art. 37, § 6º, a responsabilidade do Estado por ação de seus agentes é objetiva: basta provar a conduta, o dano e o nexo causal. A culpa do agente só importa para o regresso.", "alternativeExplanations": {"V": "Incorreto. A responsabilidade por ação do agente é objetiva.", "F": "Correto. A responsabilidade por ação do agente é objetiva."}, "tags": ["responsabilidade-civil", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["responsabilidade-civil"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-m-07", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Servidores públicos", "subtopic": "Exercício", "difficulty": "medio", "type": "true-false", "statement": "Pela Lei 8.112/1990, o servidor empossado tem 15 dias para entrar em exercício.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 15, § 1º, da Lei 8.112/1990 fixa em 15 dias, contados da posse, o prazo para o servidor entrar em exercício.", "alternativeExplanations": {"V": "Correto. O prazo para entrar em exercício é de 15 dias.", "F": "Incorreto. O prazo para entrar em exercício é de 15 dias."}, "tags": ["servidores-publicos", "lei-8112", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["servidores-publicos", "lei-8112"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-a-01", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Efeitos da anulação", "difficulty": "avancado", "type": "true-false", "statement": "A anulação de um ato administrativo ilegal produz, em regra, efeitos retroativos (ex tunc).", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "Como o ato ilegal não gera direitos, a anulação retroage à data em que foi praticado, ressalvados os terceiros de boa-fé. A revogação, por sua vez, produz efeitos para o futuro (ex nunc).", "alternativeExplanations": {"V": "Correto. Anulação retroage; revogação vale para o futuro.", "F": "Incorreto. Anulação retroage; revogação vale para o futuro."}, "tags": ["atos-administrativos", "anulacao", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos", "anulacao"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-a-02", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Atos administrativos", "subtopic": "Revogação", "difficulty": "avancado", "type": "true-false", "statement": "O Poder Judiciário, ao julgar uma ação, pode revogar ato administrativo de outro Poder por considerá-lo inconveniente.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A revogação envolve juízo de mérito (conveniência e oportunidade) e só pode ser feita pela própria Administração que praticou o ato. O Judiciário, na função jurisdicional, controla a legalidade e pode anular.", "alternativeExplanations": {"V": "Incorreto. O Judiciário anula atos ilegais, mas não revoga atos de outro Poder.", "F": "Correto. O Judiciário anula atos ilegais, mas não revoga atos de outro Poder."}, "tags": ["atos-administrativos", "controle", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["atos-administrativos", "controle"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-a-03", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Organização administrativa", "subtopic": "Agências reguladoras", "difficulty": "avancado", "type": "true-false", "statement": "As agências reguladoras federais são, em regra, autarquias em regime especial.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "As agências reguladoras, como Anatel e Aneel, são autarquias em regime especial, com maior autonomia e mandato fixo de seus dirigentes (Lei 13.848/2019).", "alternativeExplanations": {"V": "Correto. Elas são autarquias em regime especial.", "F": "Incorreto. Elas são autarquias em regime especial."}, "tags": ["organizacao-administrativa", "agencias-reguladoras", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-administrativa", "agencias-reguladoras"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-a-04", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Licitações e contratos", "subtopic": "Modalidades", "difficulty": "avancado", "type": "true-false", "statement": "Pela Lei 14.133/2021, a tomada de preços continua sendo a modalidade para contratações de valor intermediário.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A Lei 14.133/2021 não manteve a tomada de preços nem o convite. A escolha da modalidade passou a depender do objeto, e não do valor.", "alternativeExplanations": {"V": "Incorreto. A tomada de preços não existe na lei nova.", "F": "Correto. A tomada de preços não existe na lei nova."}, "tags": ["licitacoes", "modalidades", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["licitacoes", "modalidades"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-a-05", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Improbidade administrativa", "subtopic": "Prescrição", "difficulty": "avancado", "type": "true-false", "statement": "Pela Lei de Improbidade Administrativa, com a redação da Lei 14.230/2021, a ação para aplicar as sanções prescreve em 8 anos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 23 da Lei 8.429/1992, com a redação da Lei 14.230/2021, fixa a prescrição em oito anos, contados da ocorrência do fato ou, nas infrações permanentes, do dia em que cessou a permanência.", "alternativeExplanations": {"V": "Correto. O prazo de prescrição é de oito anos.", "F": "Incorreto. O prazo de prescrição é de oito anos."}, "tags": ["improbidade", "prescricao", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["improbidade", "prescricao"], "origin": "nabulab"},
  {"id": "direito-administrativo-conc-v1-vf-a-06", "area": "Concursos Públicos", "subject": "direito-administrativo", "subjectName": "Direito Administrativo", "topic": "Processo administrativo", "subtopic": "Decadência", "difficulty": "avancado", "type": "true-false", "statement": "Segundo a Lei 9.784/1999, a Administração pode anular a qualquer tempo atos que geraram efeitos favoráveis ao destinatário, mesmo que ele tenha agido de boa-fé.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O art. 54 fixa prazo decadencial de cinco anos para anular atos favoráveis aos destinatários, salvo comprovada má-fé. Passado esse prazo, o ato se estabiliza.", "alternativeExplanations": {"V": "Incorreto. Há prazo de cinco anos, salvo má-fé.", "F": "Correto. Há prazo de cinco anos, salvo má-fé."}, "tags": ["processo-administrativo", "decadencia", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["processo-administrativo", "decadencia"], "origin": "nabulab"},
];
